    const target = box || lab;
    try { target.click(); out.domClicked = String(target.tagName || '').toLowerCase() + (box ? ' (the box)' : ' (the label)'); }
    catch (e) { out.domClickError = String((e && e.message) || e); }
  }
  return out;
})()

